module find_longest_subsequence(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input [2:0] start_index,\n    input [7:0] b0, b1, b2, b3,\n    input [2:0] m,\n    output reg [3:0] length,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n    \n    reg [1:0] state, next_state;\n    reg [2:0] current_index;\n    reg [3:0] count;\n    wire [7:0] current_element;\n    \n    // Current element selection\n    assign current_element = (\n        (current_index == 3'd0) ? arr_0 :\n        (current_index == 3'd1) ? arr_1 :\n        (current_index == 3'd2) ? arr_2 :\n        (current_index == 3'd3) ? arr_3 :\n        (current_index == 3'd4) ? arr_4 :\n        (current_index == 3'd5) ? arr_5 :\n        (current_index == 3'd6) ? arr_6 : arr_7\n    );\n    \n    // Element in set check (based on m)\n    wire element_in_set;\n    assign element_in_set = (\n        (m >= 3'd1 && current_element == b0) ||\n        (m >= 3'd2 && current_element == b1) ||\n        (m >= 3'd3 && current_element == b2) ||\n        (m >= 3'd4 && current_element == b3)\n    );\n    \n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_index <= 3'd0;\n            count <= 4'd0;\n            length <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        current_index <= start_index;\n                        count <= 4'd1;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (element_in_set) begin\n                        count <= count + 4'd1;\n                        if (current_index < 3'd7) current_index <= current_index + 3'd1;\n                    end\n                end\n                \n                FINISH: begin\n                    length <= count;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        case (state)\n            IDLE:   next_state = start ? COMPUTE : IDLE;\n            \n            COMPUTE: begin\n                if (!element_in_set || current_index >= 3'd7)\n                    next_state = FINISH;\n                else\n                    next_state = COMPUTE;\n            end\n            \n            FINISH:   next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Done signal logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n        end else if (state == FINISH) begin\n            done <= 1'b1;\n        end else if (state == IDLE) begin\n            done <= 1'b0;\n        end\n    end\nendmodule